args.command:
node --input-type=module <<'EOF'
import { permit } from './limit.mjs';
const cases = [
  [-1, false], [0, true], [3, true], [4, false],
  ['1', false], [null, false], [NaN, false], [1.5, false], [Infinity, false], [undefined, false]
];
let ok = true;
for (const [input, expected] of cases) {
  const actual = permit(input);
  const pass = Object.is(actual, expected);
  console.log(`${pass ? 'PASS' : 'FAIL'} permit(${String(input)}) => ${actual}, expected ${expected}`);
  if (!pass) ok = false;
}
process.exit(ok ? 0 : 1);
EOF
